"use strict";exports.id=6158,exports.ids=[6158],exports.modules={16158:(a,b,c)=>{c.d(b,{JN:()=>f,Ty:()=>d,nU:()=>k});let d=a=>"coffee"===a.returnsPolicy,e=(a,b)=>b?`EGP ${a.toLocaleString("en-US")}`:`${a.toLocaleString("en-US")} ج`;function f(a,b,c){let d="en"===c,f=d?"?lang=en":"",g={brand:d?b.brand.nameEn:b.brand.nameAr,fee:e(b.shippingEgp,d),free:b.freeShippingOverEgp?e(b.freeShippingOverEgp,d):"",above:e(b.risk.depositAboveEgp,d),deposit:e(b.risk.depositEgp,d),cash:Math.round(100*b.wallet.cashback),days:b.wallet.expiresDays,wa:b.brand.whatsapp?b.brand.whatsapp.replace(/^(\d{4})(\d{3})(\d{4})$/,"$1 $2 $3"):"",returns:`/returns${f}`,shipping:`/shipping${f}`,privacy:`/privacy${f}`,terms:`/terms${f}`};return(d?j:i)[a](g)}let g="آخر تحديث: 19 نوفمبر 2026",h="Last updated: 19 November 2026",i={privacy:a=>({title:"سياسة الخصوصية",updated:g,lead:`بنجمع أقل بيانات ممكنة عشان نوصّلك طلبك ونخدمك، و**مش بنبيع بياناتك لأي حد**. الصفحة دي بتشرح إيه اللي بنجمعه في ${a.brand} وبنعمل بيه إيه.`,sections:[{h:"1. البيانات اللي بنجمعها",items:["**عند الطلب:** اسمك ورقم موبايلك والمحافظة والمنطقة والعنوان والعلامة المميزة، والمنتجات اللي طلبتها وطريقة الدفع.","**حسابك (لو عملته):** رقم موبايلك وكلمة سر محفوظة بشكل مشفّر، وطلباتك ورصيد محفظتك.","**طلب ما اكتملش:** لو كتبت رقمك في صفحة إتمام الطلب ومكملتش، بنحفظ السلة ورقمك واسمك ومحافظتك، وممكن حد من فريقنا يبعتلك رسالة تذكير واحدة على واتساب.","**زيارات الموقع:** بنعدّ الزيارات من غير كوكيز تتبّع، برمز بيتغير كل يوم ومينفعش يرجع لعنوان IP. وبنعرف مصدر الزيارة (إعلان، إنستجرام…) عشان نقيس إعلاناتنا.","**لو راسلتنا** على واتساب أو ماسنجر أو إنستجرام: الرسائل نفسها. على ماسنجر وإنستجرام ممكن يرد مساعد آلي بالذكاء الاصطناعي (Claude من Anthropic)، وبنشيل أرقام الموبايل والإيميلات من الرسائل قبل ما تتبعتله."]},{h:"2. بنستخدمها في إيه",items:["نجهّز طلبك ونوصّله ونتواصل معاك بخصوصه، وخدمة العملاء.","حسابك ومحفظتك والكاش باك.","نقيس إعلاناتنا ونحسّنها.","نمنع الطلبات الوهمية: الرقم اللي يرفض استلام طلبين ما بيقدرش يطلب تاني من متاجرنا، إلا بعد ما يتواصل معانا على واتساب."]},{h:"3. مين بيشوف بياناتك",items:["**شركة الشحن (بوسطة):** الاسم والرقم والعنوان عشان التوصيل.","**المحمصة اللي بتجهّز طلبك:** تفاصيل الطلب اللي محتاجاها عشان تجهّزه.","**ميتا (فيسبوك وإنستجرام):** عشان نقيس الإعلانات، بنبعت رقمك واسمك الأول ومحافظتك **بشكل مشفّر بس**، وبكسل ميتا موجود على الموقع.","**مزوّدي الخدمة** اللي بيشغّلوا المتجر (الاستضافة وقاعدة البيانات والمساعد الآلي)، وبيستخدموها لحسابنا بس.","مش بنبيع بياناتك ولا بنأجّرها لأي حد."]},{h:"4. الكوكيز والتخزين في المتصفح",text:"بنستخدم كوكي للغة وكوكي لتسجيل الدخول بس، والسلة واختياراتك بتتحفظ في متصفحك. بكسل ميتا بيستخدم الكوكيز بتاعته لقياس الإعلانات."},{h:"5. مدة الاحتفاظ",text:"بنحتفظ بالبيانات طول ما هي لازمة للأغراض دي، أو طول المدة اللي القانون يلزمنا بيها (زي سجلات الطلبات والحسابات)."},{id:"delete",h:"6. حقوقك وحذف بياناتك",items:[`تقدر تطلب نسخة من بياناتك أو تعديلها أو **حذفها** في أي وقت برسالة على واتساب ${a.wa} من نفس رقمك.`,"بنحذفها خلال 30 يوم، ما عدا اللي القانون يلزمنا نحتفظ بيه.","ولو مش عايز رسائل تذكير، ابعتلنا وهنوقفها."]},{h:"7. التواصل",text:`أي سؤال عن خصوصيتك: واتساب ${a.wa}. وراجع كمان [الشروط والأحكام](${a.terms}).`}]}),shipping:a=>({title:"الشحن والتوصيل",updated:g,lead:`بنوصّل لكل محافظات مصر مع بوسطة. الشحن **${a.fee}** لأي محافظة${a.free?`، و**مجاني** للطلبات من ${a.free}`:""}.`,sections:[{h:"1. مدة التوصيل",items:["القاهرة والجيزة والقليوبية: غالبًا خلال يومين عمل.","باقي المحافظات: غالبًا خلال 3 أيام عمل (الجمعة مش يوم عمل).","التاريخ المتوقع لمحافظتك بيظهر في صفحة المنتج وقبل تأكيد الطلب، والمندوب بيكلمك قبل ما يوصل."]},{h:"2. الرسوم",items:[`الشحن ${a.fee} لأي محافظة، ومفيش أي رسوم تانية.`,...a.free?[`مجاني للطلبات من ${a.free} (على قيمة المنتجات قبل كود الخصم).`]:[]]},{h:"3. الدفع",items:["**كاش عند الاستلام** للمندوب، أو **إنستاباي / محفظة موبايل** بعد تأكيد الطلب.",`الطلبات فوق ${a.above}: بنطلب ${a.deposit} بس مقدمًا على إنستاباي (قد مصاريف الشحن)، وبيتخصم من الإجمالي، وبيرجعلك كامل لو الطلب اتأخر أو مش مطابق.`]},{h:"4. عند الاستلام",items:["افتح الشحنة وشوف الأكياس قبل ما تدفع، **من غير ما تفتح كيس القهوة نفسه**.","الكيس اللي يتفتح عند الاستلام ما ينفعش يترفض ويُدفع تمنه.","القهوة بتوصل في أكياسها المقفولة من المحمصة."]},{h:"5. لو مش هتكون موجود",text:`ابعتلنا على واتساب ${a.wa} قبلها ونرتّب ميعاد تاني. رفض استلام طلبين من غير سبب بيوقف الطلبات على رقمك، إلا بعد ما تتواصل معانا.`},{h:"6. الإلغاء والاسترجاع",text:`تقدر تلغي مجانًا قبل الشحن. وللاسترجاع والاستبدال راجع [سياسة الاسترجاع والاستبدال](${a.returns}).`}]}),terms:a=>({title:"الشروط والأحكام",updated:g,lead:`${a.brand} متجر قهوة مختصة أونلاين في مصر، بنبيع قهوة من محامص مصرية مختارة. لما تستخدم الموقع أو تطلب منه، بتوافق على الشروط دي وعلى [سياسة الاسترجاع](${a.returns}) و[الشحن](${a.shipping}) و[الخصوصية](${a.privacy}).`,sections:[{h:"1. الطلبات",items:["طلبك بيتأكد بعد ما نراجعه، وممكن نتواصل معاك لتأكيده.","من حقنا نلغي طلب لو المنتج خلص، أو السعر ظهر غلط، أو البيانات مش كاملة. ولو كنت دفعت أي مبلغ بيرجعلك كامل."]},{h:"2. الأسعار والمنتجات",items:["الأسعار بالجنيه المصري، والسعر اللي بتدفعه هو اللي ظهر وقت الطلب. الشحن بيظهر قبل التأكيد.","الصور والوصف والنكهات من المحمصة. الطعم ودرجة التحميص تجربة شخصية، ونكهات كل قهوة مكتوبة في صفحتها."]},{h:"3. أكواد الخصم والعروض",items:["كود خصم واحد للطلب، وبالشروط المكتوبة معاه (مثلًا بعض الأكواد ما بتنطبقش على الباقات أو الشحن).",`القهوة المشتراة ضمن عرض أو خصم لا تُرجع ولا تُستبدل، زي ما في [سياسة الاسترجاع](${a.returns}).`]},{h:"4. المحفظة والكاش باك",items:[`بعد توصيل طلبك بيرجعلك ${a.cash}% من قيمة المنتجات رصيد في محفظتك على المتجر، صالح ${a.days} يوم.`,"الرصيد بتستخدمه في طلبات جاية، ومبيدفعش الشحن، ومينفعش يتحول لفلوس."]},{h:"5. حسابك",text:"انت مسؤول عن سرية كلمة السر بتاعتك وعن الطلبات اللي بتتعمل من حسابك."},{h:"6. المسؤولية",text:"مسؤوليتنا عن أي طلب ما تزيدش عن قيمته اللي دفعتها. ولا ينتقص ده من حقوقك وفقًا لقانون حماية المستهلك المصري."},{h:"7. القانون",text:"الشروط دي بتخضع لقوانين جمهورية مصر العربية."},{h:"8. التعديلات",text:`ممكن نحدّث الشروط دي، والنسخة المنشورة وقت طلبك هي اللي بتنطبق عليه. أي سؤال: واتساب ${a.wa}.`}]})},j={privacy:a=>({title:"Privacy policy",updated:h,lead:`We collect as little as we can to deliver your order and help you, and **we never sell your data**. This page explains what ${a.brand} collects and what we do with it.`,sections:[{h:"1. What we collect",items:["**When you order:** your name, phone number, governorate, area, address and landmark, what you ordered and how you pay.","**Your account (if you make one):** your phone number and an encrypted password, your orders and your wallet balance.","**An unfinished checkout:** if you type your number at checkout and don’t finish, we keep the cart, your number, name and governorate, and someone from our team may send you one reminder on WhatsApp.","**Site visits:** we count visits without tracking cookies, using a code that changes every day and can’t be turned back into an IP address. We note where a visit came from (an ad, Instagram…) to measure our ads.","**If you message us** on WhatsApp, Messenger or Instagram: the messages themselves. On Messenger and Instagram an AI assistant (Claude by Anthropic) may reply; phone numbers and emails are removed from the messages before they are sent to it."]},{h:"2. What we use it for",items:["Preparing and delivering your order, contacting you about it, and customer service.","Your account, wallet and cashback.","Measuring and improving our ads.","Stopping fake orders: a number that refuses two deliveries can’t order from our stores again until it contacts us on WhatsApp."]},{h:"3. Who sees your data",items:["**The courier (Bosta):** your name, number and address, to deliver.","**The roaster preparing your order:** the order details it needs to prepare it.","**Meta (Facebook and Instagram):** to measure ads, we send your phone, first name and governorate **in hashed form only**, and the Meta Pixel runs on the site.","**Service providers** that run the store (hosting, database, the AI assistant), only on our behalf.","We never sell or rent your data to anyone."]},{h:"4. Cookies and browser storage",text:"We use only a language cookie and a sign-in cookie; your cart and choices are kept in your browser. The Meta Pixel uses its own cookies to measure ads."},{h:"5. How long we keep it",text:"As long as it’s needed for these purposes, or as long as the law requires (such as order and accounting records)."},{id:"delete",h:"6. Your rights and deleting your data",items:[`You can ask for a copy of your data, a correction, or for it to be **deleted** at any time by messaging us on WhatsApp ${a.wa} from the same number.`,"We delete it within 30 days, except what the law requires us to keep.","If you don’t want reminders, tell us and we’ll stop them."]},{h:"7. Contact",text:`Any question about your privacy: WhatsApp ${a.wa}. See also our [terms](${a.terms}).`}]}),shipping:a=>({title:"Shipping and delivery",updated:h,lead:`We deliver to every governorate in Egypt with Bosta. Delivery is **${a.fee}** to any governorate${a.free?`, **free** on orders from ${a.free}`:""}.`,sections:[{h:"1. Delivery times",items:["Cairo, Giza and Qalyubia: usually within 2 business days.","Other governorates: usually within 3 business days (Friday isn’t a business day).","The expected date for your governorate shows on the product page and before you confirm, and the courier calls before arriving."]},{h:"2. Fees",items:[`Delivery is ${a.fee} to any governorate, with no other fees.`,...a.free?[`Free on orders from ${a.free} (on the goods, before any promo code).`]:[]]},{h:"3. Payment",items:["**Cash on delivery** to the courier, or **InstaPay / mobile wallet** after the order is confirmed.",`Orders over ${a.above}: we ask for ${a.deposit} only in advance by InstaPay (the size of the delivery fee); it comes off the total and is refunded in full if the order is late or not as ordered.`]},{h:"4. On delivery",items:["Open the parcel and check the bags before you pay, **without opening a coffee bag**.","A bag opened at delivery can’t be refused and must be paid for.","Coffee arrives in its sealed bags from the roaster."]},{h:"5. If you won’t be there",text:`Message us on WhatsApp ${a.wa} beforehand and we’ll arrange another time. Refusing two deliveries without a reason stops orders on your number until you contact us.`},{h:"6. Cancelling and returns",text:`You can cancel free of charge before your order ships. For returns and exchanges, see our [returns policy](${a.returns}).`}]}),terms:a=>({title:"Terms and conditions",updated:h,lead:`${a.brand} is an online specialty coffee store in Egypt, selling coffee from selected Egyptian roasters. By using the site or ordering from it, you agree to these terms and to our [returns](${a.returns}), [shipping](${a.shipping}) and [privacy](${a.privacy}) policies.`,sections:[{h:"1. Orders",items:["Your order is confirmed once we’ve reviewed it; we may contact you to confirm it.","We may cancel an order if the product is sold out, a price was shown wrongly, or the details are incomplete. Anything you paid is refunded in full."]},{h:"2. Prices and products",items:["Prices are in Egyptian pounds; you pay the price shown when you order. Delivery shows before you confirm.","Photos, descriptions and tasting notes come from the roaster. Taste and roast level are personal; each coffee’s notes are on its page."]},{h:"3. Promo codes and offers",items:["One promo code per order, on the conditions shown with it (some codes don’t apply to bundles or delivery).",`Coffee bought on an offer or discount can’t be returned or exchanged, as our [returns policy](${a.returns}) says.`]},{h:"4. Wallet and cashback",items:[`After your order is delivered, ${a.cash}% of the goods comes back as credit in your store wallet, valid for ${a.days} days.`,"Credit is for future orders; it doesn’t pay for delivery and can’t be turned into cash."]},{h:"5. Your account",text:"You’re responsible for keeping your password secret and for orders placed from your account."},{h:"6. Liability",text:"Our liability for any order is limited to the amount you paid for it. This doesn’t take away your rights under Egypt’s Consumer Protection Law."},{h:"7. Law",text:"These terms are governed by the laws of the Arab Republic of Egypt."},{h:"8. Changes",text:`We may update these terms; the version published when you order applies to that order. Questions: WhatsApp ${a.wa}.`}]})};function k(a){let b=[],c=0;for(let d of a.matchAll(/\*\*(.+?)\*\*|\[(.+?)\]\((\/[^)\s]*)\)/g))d.index>c&&b.push({text:a.slice(c,d.index)}),b.push(void 0!==d[1]?{text:d[1],bold:!0}:{text:d[2],href:d[3]}),c=d.index+d[0].length;return c<a.length&&b.push({text:a.slice(c)}),b}}};